```python
import re

def validate_IPv4(s):
    pattern = r'^(\d{1,3}\.){3}\d{1,3}$'
    if not re.match(pattern, s):
        return False
    parts = s.split(".")
    for part in parts:
        if not (0 <= int(part) <= 255):
            return False
    return True
```

